package com.productionhouse.crm.mediahouse.postproduction.service;
import com.productionhouse.crm.mediahouse.media.repository.MediaAssetRepository;import com.productionhouse.crm.mediahouse.postproduction.dto.PostProductionTaskRequest;import com.productionhouse.crm.mediahouse.postproduction.entity.PostProductionTask;import com.productionhouse.crm.mediahouse.postproduction.repository.PostProductionTaskRepository;import com.productionhouse.crm.auth.api.ApiException;import com.productionhouse.crm.auth.repository.UserRepository;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.any;import static org.mockito.Mockito.*;
class PostProductionTaskServiceTest{
@Test void validatesPostProductionStatusAndDateRules(){var repo=mock(PostProductionTaskRepository.class);var service=new PostProductionTaskService(repo,mock(MediaAssetRepository.class),mock(UserRepository.class));var badStatus=new PostProductionTaskRequest("Edit",null,null,null,null,"ACTIVE",null,null,null,null,null,true);assertThrows(ApiException.class,()->service.create(badStatus));var badDate=new PostProductionTaskRequest("Edit",null,null,null,null,"NOT_STARTED",null,java.time.LocalDate.parse("2026-11-02"),java.time.LocalDate.parse("2026-11-01"),null,null,true);assertThrows(ApiException.class,()->service.create(badDate));verify(repo,never()).save(any(PostProductionTask.class));}
@Test void completedTaskCannotReturnToProgress(){var repo=mock(PostProductionTaskRepository.class);var task=new PostProductionTask();task.setName("Edit");task.setStatus("COMPLETED");org.springframework.test.util.ReflectionTestUtils.setField(task,"id",4L);when(repo.findById(4L)).thenReturn(java.util.Optional.of(task));var service=new PostProductionTaskService(repo,mock(MediaAssetRepository.class),mock(UserRepository.class));var request=new PostProductionTaskRequest("Edit",null,null,null,null,"IN_PROGRESS",null,null,null,null,null,true);assertThrows(ApiException.class,()->service.update(4L,request));}
@Test void rejectsUnknownMediaReference(){var repo=mock(PostProductionTaskRepository.class);var media=mock(MediaAssetRepository.class);when(media.findById(8L)).thenReturn(java.util.Optional.empty());var service=new PostProductionTaskService(repo,media,mock(UserRepository.class));var request=new PostProductionTaskRequest("Edit",null,null,8L,null,"NOT_STARTED",null,null,null,null,null,true);assertThrows(ApiException.class,()->service.create(request));}
}
